import { useState, useEffect, useContext } from "react";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";
import { useNavigate } from "react-router-dom";
import {
  Home,
  Users,
  FileText,
  BarChart2,
  ClipboardList,
  LogOut,
} from "lucide-react";

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});

  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  // ---------------- Unified error handler ----------------
  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      alert(err.response?.data?.error || err.message);
    }
  };

  // ---------------- Backend API calls ----------------
  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/voting-state");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const rejectUser = async (id) => {
    try {
      await api.post(`/admin/reject-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const generateReport = async () => {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.hash);
    } catch (err) {
      handleApiError(err);
    }
  };

  const deleteCandidate = async (id) => {
    if (!window.confirm("Delete this candidate?")) return;
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchResults = async () => {
    try {
      const res = await api.get("/admin/results");
      setResults(res.data.positionResults);
      setWinners(res.data.winners);
    } catch (err) {
      handleApiError(err);
    }
  };

  // ---------------- Initial load ----------------
  useEffect(() => {
    if (!token) {
      navigate("/login");
      return;
    }

    const init = async () => {
      await fetchVotingState();
      await fetchPendingUsers();
      await fetchCandidates();
      await fetchLogs();
      await fetchResults();
    };
    init();
  }, [token]);

  // ---------------- JSX ----------------
  return (
    <div className="flex min-h-screen bg-gray-100">
      {/* Sidebar */}
      <aside className="w-64 bg-white border-r shadow-sm flex flex-col">
        <div className="px-6 py-4 border-b">
          <h1 className="text-xl font-bold text-blue-700">iVote Admin</h1>
        </div>
        <nav className="flex-1 px-4 py-6 space-y-2 text-sm">
          <a href="#status" className="flex items-center gap-2 p-2 rounded-md hover:bg-gray-100 text-gray-700">
            <Home size={16} /> Dashboard
          </a>
          <a href="#users" className="flex items-center gap-2 p-2 rounded-md hover:bg-gray-100 text-gray-700">
            <Users size={16} /> Users
          </a>
          <a href="#candidates" className="flex items-center gap-2 p-2 rounded-md hover:bg-gray-100 text-gray-700">
            <ClipboardList size={16} /> Candidates
          </a>
          <a href="#results" className="flex items-center gap-2 p-2 rounded-md hover:bg-gray-100 text-gray-700">
            <BarChart2 size={16} /> Results
          </a>
          <a href="#reports" className="flex items-center gap-2 p-2 rounded-md hover:bg-gray-100 text-gray-700">
            <FileText size={16} /> Reports
          </a>
          <a href="#logs" className="flex items-center gap-2 p-2 rounded-md hover:bg-gray-100 text-gray-700">
            <ClipboardList size={16} /> Logs
          </a>
        </nav>
        <div className="px-4 py-4 border-t">
          <button
            onClick={() => { logout(); navigate("/login"); }}
            className="flex items-center gap-2 w-full px-3 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 text-sm font-medium"
          >
            <LogOut size={16} /> Logout
          </button>
        </div>
      </aside>

      {/* Main content */}
      <main className="flex-1 p-8 space-y-8">
        {/* Voting Status */}
        <section id="status" className="bg-white p-6 rounded-lg shadow border">
          <div className="flex justify-between items-center">
            <div>
              <h2 className="text-lg font-semibold text-gray-800">Voting Status</h2>
              <p className={`mt-1 font-medium ${votingOpen ? "text-green-600" : "text-red-600"}`}>
                {votingOpen ? "Open" : "Closed"}
              </p>
            </div>
            <button
              onClick={toggleVoting}
              className={`px-5 py-2 rounded-md text-sm font-medium text-white transition ${
                votingOpen ? "bg-red-600 hover:bg-red-700" : "bg-green-600 hover:bg-green-700"
              }`}
            >
              {votingOpen ? "Close Voting" : "Open Voting"}
            </button>
          </div>
        </section>

        {/* Pending Users */}
        <section id="users" className="bg-white p-6 rounded-lg shadow border">
          <h2 className="text-lg font-semibold text-gray-800 mb-4">Pending Voter Registrations</h2>
          {pendingUsers.length === 0 ? (
            <p className="text-gray-500 italic">No pending users.</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm border border-gray-200 rounded-lg">
                <thead className="bg-gray-50 text-gray-700 text-xs uppercase">
                  <tr>
                    <th className="px-4 py-2 text-left">Student Number</th>
                    <th className="px-4 py-2 text-left">Name</th>
                    <th className="px-4 py-2 text-left">Email</th>
                    <th className="px-4 py-2 text-center">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {pendingUsers.map((user, i) => (
                    <tr
                      key={user.id}
                      className={`border-t ${i % 2 === 0 ? "bg-gray-50" : "bg-white"} hover:bg-gray-100`}
                    >
                      <td className="px-4 py-2">{user.studentNumber}</td>
                      <td className="px-4 py-2">{user.name}</td>
                      <td className="px-4 py-2">{user.email}</td>
                      <td className="px-4 py-2 text-center space-x-2">
                        <button
                          onClick={() => approveUser(user.id)}
                          className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700 text-xs font-medium"
                        >
                          Approve
                        </button>
                        <button
                          onClick={() => rejectUser(user.id)}
                          className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700 text-xs font-medium"
                        >
                          Reject
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>

        {/* Candidates */}
        <section id="candidates" className="bg-white p-6 rounded-lg shadow border">
          <h2 className="text-lg font-semibold text-gray-800 mb-4">Candidates</h2>
          <div className="overflow-x-auto">
            <table className="w-full text-sm border border-gray-200 rounded-lg">
              <thead className="bg-gray-50 text-gray-700 text-xs uppercase">
                <tr>
                  <th className="px-4 py-2 text-left">Name</th>
                  <th className="px-4 py-2 text-left">Position</th>
                  <th className="px-4 py-2 text-left">Party</th>
                  <th className="px-4 py-2 text-center">Actions</th>
                </tr>
              </thead>
              <tbody>
                {candidates.map((c, i) => (
                  <tr
                    key={c.id}
                    className={`border-t ${i % 2 === 0 ? "bg-gray-50" : "bg-white"} hover:bg-gray-100`}
                  >
                    <td className="px-4 py-2">{c.name}</td>
                    <td className="px-4 py-2">{c.position}</td>
                    <td className="px-4 py-2">{c.party || "-"}</td>
                    <td className="px-4 py-2 text-center">
                      <button
                        onClick={() => deleteCandidate(c.id)}
                        className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700 text-xs font-medium"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>

        {/* Election Results */}
        <section id="results" className="bg-white p-6 rounded-lg shadow border">
          <h2 className="text-lg font-semibold text-gray-800 mb-4">Election Results</h2>
          {Object.keys(results).length === 0 ? (
            <p className="text-gray-500 italic">No results available yet.</p>
          ) : (
            Object.keys(results).map((pos) => (
              <div key={pos} className="mb-6">
                <h3 className="text-md font-semibold text-gray-700 mb-2">{pos}</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm border border-gray-200 rounded-lg">
                    <thead className="bg-gray-50 text-gray-700 text-xs uppercase">
                      <tr>
                        <th className="px-4 py-2 text-left">Name</th>
                        <th className="px-4 py-2 text-left">Party</th>
                        <th className="px-4 py-2 text-center">Votes</th>
                        <th className="px-4 py-2 text-center">Status</th>
                      </tr>
                    </thead>
                    <tbody>
                      {results[pos].map((c, i) => (
                        <tr
                          key={c.id}
                          className={`border-t ${i % 2 === 0 ? "bg-gray-50" : "bg-white"} hover:bg-gray-100`}
                        >
                          <td className="px-4 py-2">{c.name}</td>
                          <td className="px-4 py-2">{c.party || "-"}</td>
                          <td className="px-4 py-2 text-center">{c.votes}</td>
                          <td className="px-4 py-2 text-center font-medium">
                            {winners[pos]?.id === c.id ? (
                              <span className="text-green-600">Winner</span>
                            ) : (
                              <span className="text-gray-400">—</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))
          )}
        </section>

        {/* Reports */}
        <section id="reports" className="bg-white p-6 rounded-lg shadow border">
          <h2 className="text-lg font-semibold text-gray-800 mb-4">Reports</h2>
          <button
            onClick={generateReport}
            className="bg-blue-600 text-white px-5 py-2 rounded-md hover:bg-blue-700 transition text-sm font-medium"
          >
            Generate Final Report
          </button>
          {reportHash && (
            <p className="mt-3 text-gray-600 text-sm">
              Cryptographic Hash: <span className="font-mono">{reportHash}</span>
            </p>
          )}
        </section>

        {/* System Logs */}
        <section id="logs" className="bg-white p-6 rounded-lg shadow border">
          <h2 className="text-lg font-semibold text-gray-800 mb-4">System Logs</h2>
          {logs.length === 0 ? (
            <p className="text-gray-500 italic">No logs available.</p>
          ) : (
            <ul className="divide-y divide-gray-200 max-h-64 overflow-y-auto text-sm">
              {logs.map((log) => (
                <li key={log.id} className="py-2 flex justify-between text-gray-700">
                  <span>{log.action}</span>
                  <span className="text-gray-400 text-xs">
                    {new Date(log.createdAt).toLocaleString()}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </section>
      </main>
    </div>
  );
}
